CREATE TABLE public.folha_referencias(
 id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),colaborador_id uuid REFERENCES public.colaboradores(id),externo_id uuid REFERENCES public.folha_externos(id),data date NOT NULL CHECK(isfinite(data)),origem_obra_id uuid NOT NULL REFERENCES public.obras(id),tipo text NOT NULL CHECK(tipo IN('garantia','outra')),referencia_original text NOT NULL CHECK(length(btrim(referencia_original)) BETWEEN 1 AND 1000),obra_original_id uuid REFERENCES public.obras(id),associada_obra_id uuid REFERENCES public.obras(id),associada_por uuid REFERENCES public.utilizadores(id),associada_em timestamptz,
 intervals jsonb NOT NULL CHECK(jsonb_typeof(intervals)='array' AND jsonb_array_length(intervals) BETWEEN 1 AND 16),minutes integer NOT NULL CHECK(minutes>=0),open boolean NOT NULL,special_day boolean NOT NULL,special_reviewed_by uuid REFERENCES public.utilizadores(id),special_reviewed_at timestamptz,revision integer NOT NULL CHECK(revision>0),criado_por uuid NOT NULL REFERENCES public.utilizadores(id),criado_em timestamptz NOT NULL DEFAULT now(),atualizado_por uuid NOT NULL REFERENCES public.utilizadores(id),atualizado_em timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL,
 CHECK(num_nonnulls(colaborador_id,externo_id)=1),CHECK(num_nonnulls(associada_obra_id,associada_por,associada_em) IN(0,3)),CHECK(num_nonnulls(special_reviewed_by,special_reviewed_at) IN(0,2))
);CREATE INDEX folha_referencias_pessoa_data_idx ON public.folha_referencias(colaborador_id,data);CREATE INDEX folha_referencias_externo_data_idx ON public.folha_referencias(externo_id,data);
CREATE TABLE public.folha_referencias_historico(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid NOT NULL REFERENCES public.empresas(id),referencia_id uuid NOT NULL REFERENCES public.folha_referencias(id),revision integer NOT NULL CHECK(revision>0),action text NOT NULL CHECK(action IN('save_reference','associate_reference','special_review_reference')),antes jsonb,depois jsonb NOT NULL,ator_id uuid NOT NULL REFERENCES public.utilizadores(id),at timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL,reason text,UNIQUE(referencia_id,revision));
ALTER TABLE public.folha_referencias ENABLE ROW LEVEL SECURITY;ALTER TABLE public.folha_referencias_historico ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.folha_referencias,public.folha_referencias_historico FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION folha_privado.referencia_guardar_v3() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $guard$
DECLARE u public.utilizadores;f jsonb;w uuid;p uuid;k text;r public.folha_referencias;
BEGIN
 IF current_user<>'postgres' OR TG_OP='DELETE' OR TG_TABLE_NAME='folha_referencias_historico' AND TG_OP<>'INSERT' THEN RAISE EXCEPTION 'REFERENCE_PROTECTED' USING ERRCODE='42501';END IF;u:=folha_privado.ator();
 IF TG_TABLE_NAME='folha_referencias_historico' THEN SELECT * INTO r FROM public.folha_referencias WHERE id=NEW.referencia_id;IF NEW.empresa_id<>u.empresa_id OR NEW.ator_id<>u.id OR NEW.depois IS DISTINCT FROM to_jsonb(r) OR NEW.revision<>r.revision OR NEW.request_id<>r.request_id OR NEW.at IS DISTINCT FROM now() THEN RAISE EXCEPTION 'REFERENCE_HISTORY_INVALID';END IF;RETURN NEW;END IF;
 IF NEW.empresa_id<>u.empresa_id OR NEW.atualizado_por<>u.id OR NEW.atualizado_em IS DISTINCT FROM now() THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;
 IF TG_OP='UPDATE' AND (NEW.id,NEW.empresa_id,NEW.colaborador_id,NEW.externo_id,NEW.data,NEW.origem_obra_id,NEW.tipo,NEW.referencia_original,NEW.obra_original_id,NEW.criado_por,NEW.criado_em) IS DISTINCT FROM (OLD.id,OLD.empresa_id,OLD.colaborador_id,OLD.externo_id,OLD.data,OLD.origem_obra_id,OLD.tipo,OLD.referencia_original,OLD.obra_original_id,OLD.criado_por,OLD.criado_em) THEN RAISE EXCEPTION 'REFERENCE_ORIGINAL_IMMUTABLE';END IF;
 IF EXISTS(SELECT 1 FROM public.folha_registos WHERE id=NEW.id) THEN RAISE EXCEPTION 'REFERENCE_ID_CONFLICT';END IF;
 IF NEW.revision<>(CASE WHEN TG_OP='INSERT' THEN 1 ELSE OLD.revision+1 END) THEN RAISE EXCEPTION 'STALE_REVISION' USING ERRCODE='40001';END IF;
 p:=coalesce(NEW.colaborador_id,NEW.externo_id);k:=CASE WHEN NEW.colaborador_id IS NULL THEN 'external' ELSE 'primeline' END;
 IF NOT EXISTS(SELECT 1 FROM public.obras WHERE id=NEW.origem_obra_id AND empresa_id=u.empresa_id) OR NEW.obra_original_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.obras WHERE id=NEW.obra_original_id AND empresa_id=u.empresa_id) OR NEW.associada_obra_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.obras WHERE id=NEW.associada_obra_id AND empresa_id=u.empresa_id) OR (k='primeline' AND NOT EXISTS(SELECT 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id)) OR (k='external' AND NOT EXISTS(SELECT 1 FROM public.folha_externos WHERE id=p AND empresa_id=u.empresa_id)) THEN RAISE EXCEPTION 'REFERENCE_TENANT_MISMATCH' USING ERRCODE='42501';END IF;
 IF TG_OP='UPDATE' AND (NEW.associada_obra_id,NEW.associada_por,NEW.associada_em) IS DISTINCT FROM (OLD.associada_obra_id,OLD.associada_por,OLD.associada_em) AND NOT folha_privado.adm_operacional() THEN RAISE EXCEPTION 'PERMISSION_DENIED: associação administrativa' USING ERRCODE='42501';END IF;
 f:=folha_privado.facts(NEW.intervals,NEW.data);IF NEW.minutes IS DISTINCT FROM (f->>'minutes')::integer OR NEW.open IS DISTINCT FROM (f->>'open')::boolean THEN RAISE EXCEPTION 'REFERENCE_FACTS_INVALID';END IF;RETURN NEW;
END $guard$;
CREATE FUNCTION folha_privado.referencia_trilho_v3() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $trail$
BEGIN IF NOT EXISTS(SELECT 1 FROM public.folha_referencias_historico WHERE referencia_id=NEW.id AND revision=NEW.revision AND depois=to_jsonb(NEW) AND ator_id=NEW.atualizado_por AND request_id=NEW.request_id) THEN RAISE EXCEPTION 'REFERENCE_HISTORY_REQUIRED';END IF;RETURN NULL;END $trail$;
CREATE FUNCTION folha_privado.referencia_reconciliar_v3() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $reconcile$
BEGIN IF NEW.colaborador_id IS NOT NULL THEN PERFORM folha_privado.diaria_recalcular(NEW.colaborador_id,NEW.data,NEW.request_id);END IF;RETURN NULL;END $reconcile$;
CREATE TRIGGER folha_referencia_guardar BEFORE INSERT OR UPDATE OR DELETE ON public.folha_referencias FOR EACH ROW EXECUTE FUNCTION folha_privado.referencia_guardar_v3();CREATE TRIGGER folha_referencia_historico_guardar BEFORE INSERT OR UPDATE OR DELETE ON public.folha_referencias_historico FOR EACH ROW EXECUTE FUNCTION folha_privado.referencia_guardar_v3();CREATE CONSTRAINT TRIGGER folha_referencia_trilho AFTER INSERT OR UPDATE ON public.folha_referencias DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION folha_privado.referencia_trilho_v3();CREATE TRIGGER folha_referencia_reconciliar AFTER INSERT OR UPDATE ON public.folha_referencias FOR EACH ROW EXECUTE FUNCTION folha_privado.referencia_reconciliar_v3();CREATE TRIGGER folha_conferencia_referencia AFTER INSERT OR UPDATE ON public.folha_referencias FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_reconciliar();
CREATE FUNCTION public.fn_folha_referencia_operar_v3(p_acao text,p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $reference$
DECLARE u public.utilizadores;req uuid:=(p_dados->>'request_id')::uuid;rid uuid:=(p_dados->>'id')::uuid;old public.folha_referencias;n public.folha_referencias;p uuid;d date;k text;f jsonb;xs jsonb;other jsonb;daily jsonb;payload jsonb;token text;outcome jsonb;op folha_privado.operacoes;cnt integer;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();PERFORM 1 FROM public.utilizadores WHERE id=u.id FOR SHARE;u:=folha_privado.ator();IF (p_dados ? 'empresa_id' AND (p_dados->>'empresa_id')::uuid IS DISTINCT FROM u.empresa_id) OR (p_dados ? 'company_id' AND (p_dados->>'company_id')::uuid IS DISTINCT FROM u.empresa_id) THEN RAISE EXCEPTION 'TENANT_HINT_MISMATCH' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.utilizadores WHERE id=u.id FOR SHARE;u:=folha_privado.ator();
 IF req IS NULL OR rid IS NULL OR p_confirmar IS NULL OR (p_dados->>'version')::integer IS DISTINCT FROM 3 OR p_acao IS NULL OR p_acao NOT IN('save_reference','associate_reference','special_review_reference') THEN RAISE EXCEPTION 'VALIDATION_ERROR';END IF;
 SELECT * INTO old FROM public.folha_referencias WHERE id=rid FOR UPDATE;IF old.id IS NOT NULL AND old.empresa_id<>u.empresa_id THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;n:=old;
 IF old.id IS NULL THEN IF p_acao<>'save_reference' THEN RAISE EXCEPTION 'REFERENCE_NOT_FOUND';END IF;n.id:=rid;n.empresa_id:=u.empresa_id;k:=p_dados->>'kind';IF k='primeline' THEN n.colaborador_id:=(p_dados->>'person_id')::uuid;ELSIF k='external' THEN n.externo_id:=(p_dados->>'person_id')::uuid;ELSE RAISE EXCEPTION 'VALIDATION_ERROR';END IF;n.data:=(p_dados->>'date')::date;n.origem_obra_id:=(p_dados->>'origin_work_id')::uuid;n.tipo:=p_dados->>'type';n.referencia_original:=p_dados->>'original_reference';n.obra_original_id:=(p_dados->>'original_work_id')::uuid;n.criado_por:=u.id;n.criado_em:=now();n.special_day:=extract(isodow FROM n.data)>5 OR EXISTS(SELECT 1 FROM public.folha_config_empresa WHERE empresa_id=u.empresa_id AND n.data=ANY(holiday_dates));END IF;
 p:=coalesce(n.colaborador_id,n.externo_id);d:=n.data;k:=CASE WHEN n.colaborador_id IS NULL THEN 'external' ELSE 'primeline' END;PERFORM folha_privado.lock_dia(p,d);
 IF k='primeline' THEN PERFORM 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id FOR SHARE;ELSE PERFORM 1 FROM public.folha_externos WHERE id=p AND empresa_id=u.empresa_id FOR SHARE;END IF;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: tenant pessoa' USING ERRCODE='42501';END IF;
 IF n.obra_original_id IS NOT NULL THEN PERFORM 1 FROM public.obras WHERE id=n.obra_original_id AND empresa_id=u.empresa_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: obra original' USING ERRCODE='42501';END IF;END IF;
 IF p_acao='save_reference' THEN PERFORM folha_privado.destino_autorizar_v3(p,n.origem_obra_id,k,true);IF k='primeline' THEN PERFORM 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id AND data_admissao<=d AND (data_saida IS NULL OR data_saida>d) FOR UPDATE;ELSE PERFORM 1 FROM public.folha_externos WHERE id=p AND empresa_id=u.empresa_id AND (ativo OR (folha_privado.adm_operacional() OR u.funcao='diretor_obra') AND old.id IS NOT NULL) FOR UPDATE;END IF;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: pessoa' USING ERRCODE='42501';END IF;
  IF k='primeline' AND NOT folha_privado.adm_operacional() AND NOT folha_privado.elegivel_equipa(p,d) AND NOT EXISTS(SELECT 1 FROM public.colaboradores WHERE id=p AND utilizador_id=u.id AND u.funcao IN('encarregado','diretor_obra','adjunto','preparador')) THEN RAISE EXCEPTION 'PERMISSION_DENIED: equipa' USING ERRCODE='42501';END IF;
  IF d<(now() AT TIME ZONE 'Europe/Lisbon')::date-1 AND NOT folha_privado.adm_operacional() AND NOT(k='external' AND u.funcao='diretor_obra') THEN RAISE EXCEPTION 'CORRECTION_WINDOW_EXCEEDED';END IF;
 ELSE IF NOT folha_privado.adm_operacional() THEN RAISE EXCEPTION 'PERMISSION_DENIED: administrativo' USING ERRCODE='42501';END IF;END IF;
 IF (d<(now() AT TIME ZONE 'Europe/Lisbon')::date-1 OR p_acao<>'save_reference' OR k='external' AND u.funcao='diretor_obra') AND nullif(btrim(p_dados->>'reason'),'') IS NULL THEN RAISE EXCEPTION 'CORRECTION_REASON_REQUIRED';END IF;
 payload:=jsonb_build_object('action',p_acao,'data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 IF (p_dados->>'expected_revision')::integer IS DISTINCT FROM coalesce(old.revision,0) THEN RAISE EXCEPTION 'STALE_REVISION' USING ERRCODE='40001';END IF;
 IF p_acao='save_reference' THEN
  IF old.id IS NOT NULL AND (p_dados ? 'original_reference' AND p_dados->>'original_reference' IS DISTINCT FROM old.referencia_original OR p_dados ? 'origin_work_id' AND (p_dados->>'origin_work_id')::uuid IS DISTINCT FROM old.origem_obra_id OR p_dados ? 'person_id' AND (p_dados->>'person_id')::uuid IS DISTINCT FROM p) THEN RAISE EXCEPTION 'REFERENCE_ORIGINAL_IMMUTABLE';END IF;
  IF k='primeline' AND (EXISTS(SELECT 1 FROM public.ausencias WHERE colaborador_id=p AND data=d) OR EXISTS(SELECT 1 FROM public.ponto_pessoal_obra WHERE colaborador_id=p AND data=d)) THEN RAISE EXCEPTION 'REFERENCE_POINT_CONFLICT';END IF;
  IF k='primeline' AND EXISTS(SELECT 1 FROM public.folha_he h JOIN public.folha_registos f ON f.id=h.folha_id WHERE f.colaborador_id=p AND f.data=d) THEN RAISE EXCEPTION 'NORMAL_HE_REQUIRES_ADMIN_REVIEW';END IF;
  IF k='external' AND NOT EXISTS(SELECT 1 FROM public.folha_externos_dias WHERE externo_id=p AND obra_id=n.origem_obra_id AND data=d) AND NOT EXISTS(SELECT 1 FROM public.folha_externos_permanencias WHERE externo_id=p AND obra_id=n.origem_obra_id AND inicio<=d AND (fim IS NULL OR fim>d)) THEN RAISE EXCEPTION 'EXTERNAL_DAY_REQUIRED';END IF;
  IF jsonb_typeof(p_dados->'intervals') IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_dados->'intervals') x WHERE x->>'mode' IS NULL OR x->>'mode' NOT IN('normal','personalizado') OR x->>'mode'='personalizado' AND x->>'period' IS NOT NULL OR x->>'mode'='normal' AND coalesce(x->>'period','') NOT IN('manha','tarde')) THEN RAISE EXCEPTION 'PERIOD_REQUIRED';END IF;
  xs:=p_dados->'intervals';f:=folha_privado.facts(xs,d);
  SELECT coalesce(jsonb_agg(x),'[]') INTO other FROM (SELECT x FROM public.folha_registos r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END UNION ALL SELECT x FROM public.folha_referencias r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE r.id<>rid AND r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) q;
  IF jsonb_array_length(other||xs)>16 THEN RAISE EXCEPTION 'INTERVAL_LIMIT';END IF;PERFORM folha_privado.facts(other||xs,d);
  SELECT count(*) INTO cnt FROM (SELECT id FROM public.folha_registos WHERE data=d AND CASE WHEN k='primeline' THEN colaborador_id=p ELSE externo_id=p END UNION ALL SELECT id FROM public.folha_referencias WHERE id<>rid AND data=d AND CASE WHEN k='primeline' THEN colaborador_id=p ELSE externo_id=p END) q;IF cnt>=4 THEN RAISE EXCEPTION 'DESTINATION_LIMIT';END IF;
  n.intervals:=xs;n.minutes:=(f->>'minutes')::integer;n.open:=(f->>'open')::boolean;n.special_reviewed_by:=NULL;n.special_reviewed_at:=NULL;
 ELSIF p_acao='associate_reference' THEN n.associada_obra_id:=(p_dados->>'associate_work_id')::uuid;IF n.associada_obra_id IS NULL THEN RAISE EXCEPTION 'ASSOCIATION_REQUIRED';END IF;PERFORM 1 FROM public.obras WHERE id=n.associada_obra_id AND empresa_id=u.empresa_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: obra associação' USING ERRCODE='42501';END IF;n.associada_por:=u.id;n.associada_em:=now();
 ELSE IF NOT n.special_day THEN RAISE EXCEPTION 'NOT_SPECIAL_DAY';END IF;n.special_reviewed_by:=u.id;n.special_reviewed_at:=now();END IF;
 IF k='primeline' THEN SELECT to_jsonb(a) INTO daily FROM public.folha_avaliacoes_diarias a WHERE colaborador_id=p AND data=d AND empresa_id=u.empresa_id FOR UPDATE;IF (p_dados->>'expected_daily_revision')::integer IS DISTINCT FROM coalesce((daily->>'revision')::integer,0) THEN RAISE EXCEPTION 'STALE_REVISION: diária' USING ERRCODE='40001';END IF;END IF;
 n.revision:=coalesce(old.revision,0)+1;n.atualizado_por:=u.id;n.atualizado_em:=now();n.request_id:=req;
 token:=encode(sha256(convert_to(jsonb_build_object('actor',u.id,'tenant',u.empresa_id,'payload',payload,'before',to_jsonb(old),'daily',daily,'source',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]') FROM (SELECT to_jsonb(r) value FROM public.folha_registos r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END UNION ALL SELECT to_jsonb(r) value FROM public.folha_referencias r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) x),'reference',CASE WHEN k='primeline' AND daily IS NULL THEN folha_privado.diaria_referencia(p,d) END,'after',to_jsonb(n)-'criado_em'-'atualizado_em'-'associada_em'-'special_reviewed_at')::text,'UTF8')),'hex');
 IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token,'preview',to_jsonb(n));END IF;IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 IF old.id IS NULL THEN INSERT INTO public.folha_referencias SELECT(n).*;ELSE UPDATE public.folha_referencias SET intervals=n.intervals,minutes=n.minutes,open=n.open,associada_obra_id=n.associada_obra_id,associada_por=n.associada_por,associada_em=n.associada_em,special_reviewed_by=n.special_reviewed_by,special_reviewed_at=n.special_reviewed_at,revision=n.revision,atualizado_por=n.atualizado_por,atualizado_em=n.atualizado_em,request_id=req WHERE id=rid;END IF;
 INSERT INTO public.folha_referencias_historico(empresa_id,referencia_id,revision,action,antes,depois,ator_id,request_id,reason) VALUES(u.empresa_id,rid,n.revision,p_acao,to_jsonb(old),to_jsonb(n),u.id,req,p_dados->>'reason');
 outcome:=jsonb_build_object('version',3,'committed',true,'request_id',req,'reference',to_jsonb(n));INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,outcome,now());RETURN outcome;
END $reference$;
CREATE FUNCTION public.fn_folha_referencias_contexto_v3(p_data date,p_obra_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $context$
DECLARE u public.utilizadores;rows jsonb;BEGIN u:=folha_privado.ator();PERFORM folha_privado.obra(p_obra_id);IF p_data IS NULL THEN RAISE EXCEPTION 'DATE_REQUIRED';END IF;SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') INTO rows FROM public.folha_referencias r WHERE r.empresa_id=u.empresa_id AND r.data=p_data AND (r.origem_obra_id=p_obra_id OR r.associada_obra_id=p_obra_id);RETURN jsonb_build_object('version',3,'work_id',p_obra_id,'date',p_data,'records',rows);END $context$;
CREATE FUNCTION folha_privado.referencia_invariante_v3() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $invariant$
DECLARE p uuid;d date;k text;xs jsonb;cnt integer;req uuid;j jsonb;
BEGIN
 j:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;p:=coalesce((j->>'colaborador_id')::uuid,(j->>'externo_id')::uuid);d:=(j->>'data')::date;k:=CASE WHEN j->>'colaborador_id' IS NULL THEN 'external' ELSE 'primeline' END;
 IF NOT EXISTS(SELECT 1 FROM public.folha_referencias r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) THEN RETURN NULL;END IF;PERFORM folha_privado.lock_dia(p,d);
 SELECT coalesce(jsonb_agg(x),'[]') INTO xs FROM (SELECT x FROM public.folha_registos r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END UNION ALL SELECT x FROM public.folha_referencias r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) q;
 IF jsonb_array_length(xs)>16 THEN RAISE EXCEPTION 'INTERVAL_LIMIT';END IF;PERFORM folha_privado.facts(xs,d);
 SELECT count(*) INTO cnt FROM (SELECT id FROM public.folha_registos r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END UNION ALL SELECT id FROM public.folha_referencias r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) q;IF cnt>4 THEN RAISE EXCEPTION 'DESTINATION_LIMIT';END IF;
 IF k='primeline' THEN req:=coalesce((j->>'request_id')::uuid,gen_random_uuid());PERFORM folha_privado.diaria_recalcular(p,d,req);END IF;RETURN NULL;
END $invariant$;
CREATE CONSTRAINT TRIGGER folha_referencia_invariante AFTER INSERT OR UPDATE OR DELETE ON public.folha_referencias DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION folha_privado.referencia_invariante_v3();
CREATE CONSTRAINT TRIGGER folha_ponto_referencia_invariante AFTER INSERT OR UPDATE OR DELETE ON public.folha_registos DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION folha_privado.referencia_invariante_v3();
